        public DataTable ExportAllDeptMISFilter(string Department, string fromdate, string todate)
        {
            string SP_Name = "";
            if (Department == "Address")
            {

                SP_Name = "MIS_addressDepartment";
            }
            else if (Department == "Education")
            {

                SP_Name = "MIS_EducationDepartment";
            }
            else if (Department == "Employment")
            {

                SP_Name = "MIS_EmploymentDepartment";

            }

            else if (Department == "Reference")
            {

                SP_Name = "MIS_ReferenceDepartment";
            }

            else if (Department == "Criminal")
            {

                SP_Name = "MIS_CriminalDepartment";
            }

            else if (Department == "National Identity")
            {

                SP_Name = "MIS_NationalIdentityDepartment";
            }

            else if (Department == "Special Check")
            {

                SP_Name = "MIS_SpecialDepartment";
            }

            else if (Department == "Report QC")
            {

                SP_Name = "MIS_RWQC_procedure";
            }

            DataTable dt = new DataTable();
            dt = DAS.ExecuteDataTable(DAS.ConnectionString, CommandType.StoredProcedure, SP_Name,


            DAS.CreateParameter("@dateFrom", SqlDbType.VarChar, fromdate, ParameterDirection.Input, 100, false),
            DAS.CreateParameter("@dateTo", SqlDbType.VarChar, todate, ParameterDirection.Input, 100, false)



            );
            return dt;
        }

