        public DataTable MIS_Client_common(int ClientRowId)
        {
            string Conn = "";
            DateTime getDt = DateTime.Now;
            string timeSlot = (getDt.Minute < 30 || (getDt.Minute == 30 && getDt.Second == 0))
                ? "BGVAPPDBN_MIS"
                : "BGVAPPDBN_MIS_TWO";
            if (timeSlot == "BGVAPPDBN_MIS")
            {
                Conn = DAS.ConnStrA.ToString();
            }
            else if (timeSlot == "BGVAPPDBN_MIS_TWO")
            {
                Conn = DAS.ConnStrB.ToString();
            }
            else
            {
                Conn = DAS.ConnectionString.ToString();
            }
            DataTable dt = new DataTable();
            dt = DAS.ExecuteDataTable(Conn, CommandType.StoredProcedure, "MIS_Client_common",
                DAS.CreateParameter("@clientid", SqlDbType.VarChar, ClientRowId, ParameterDirection.Input, 4000, false)

            );
            return dt;
        }

