        public DataSet MIS_LTIMindtree_Trackar()
        {
            string Conn = "";
            DateTime getDt = DateTime.Now;
            string timeSlot = (getDt.Minute < 30 || (getDt.Minute == 30 && getDt.Second == 0))
                ? "BGVMIS_49"
                : "BGVMISTWO_49";
            if (timeSlot == "BGVMIS_49")
            {
                Conn = DAS.BGVMIS_49.ToString();
            }
            else if (timeSlot == "BGVMISTWO_49")
            {
                Conn = DAS.BGVMISTWO_49.ToString();
            }
            else
            {
                Conn = DAS.ConnectionString.ToString();
            }
            DataSet ds = new DataSet();
            ds = DAS.ExecuteDataset(Conn, CommandType.StoredProcedure, "LTIMindtree_Trackar"


            );
            return ds;
        }
