        public DataTable FilterPurgeTargets_DB(int clientRowID, List<string> processedList, string PurgDateFrom, string PurgDateTo, string fileNameReq)
        {
          
            DataTable refTable = new DataTable();
            refTable.Columns.Add("Item", typeof(string));  

            foreach (var refNo in processedList)
            {
                refTable.Rows.Add(refNo);
            }

        
            DataTable dt = DAS.ExecuteDataTable(
                DAS.ConnectionString,
                CommandType.StoredProcedure,
                "sp_FilterPurgeTargets",
                DAS.CreateParameter("@ClientRowID", SqlDbType.Int, clientRowID, ParameterDirection.Input, 0, false),
                DAS.CreateParameter("@RefNos", SqlDbType.Structured, refTable, ParameterDirection.Input, 0, false),
                DAS.CreateParameter("@PurgDateFrom", SqlDbType.VarChar, PurgDateFrom, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@PurgDateTo", SqlDbType.VarChar, PurgDateTo, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@FileNamePurgData", SqlDbType.VarChar, fileNameReq, ParameterDirection.Input, 100, false)
            );

            return dt;
        }

