        public int OperationAllocation_With_Type(List<int> candCheckRowIds, int allocateId, string status)
        {
            int intReturnValue = 0;

            using (SqlConnection conn = new SqlConnection(DAS.ConnectionString))
            {
                using (SqlCommand cmd = new SqlCommand("OperationAllocation_With_Type", conn))
                {
                    cmd.CommandType = CommandType.StoredProcedure;

                    // Create table-valued parameter
                    DataTable candCheckRowIdTable = new DataTable();
                    candCheckRowIdTable.Columns.Add("CandCheckRowID", typeof(int));

                    foreach (int id in candCheckRowIds)
                    {
                        candCheckRowIdTable.Rows.Add(id);
                    }

                    // Add TVP parameter
                    SqlParameter tvpParam = cmd.Parameters.AddWithValue("@CandCheckRowIDs", candCheckRowIdTable);
                    tvpParam.SqlDbType = SqlDbType.Structured;
                    tvpParam.TypeName = "dbo.CheckRowIdList";

                    // Other parameters
                    cmd.Parameters.AddWithValue("@AllocateId", allocateId);
                    cmd.Parameters.AddWithValue("@Status", status);

                    // Return value
                    SqlParameter returnValueParam = new SqlParameter();
                    returnValueParam.Direction = ParameterDirection.ReturnValue;
                    returnValueParam.SqlDbType = SqlDbType.Int;
                    cmd.Parameters.Add(returnValueParam);

                    conn.Open();
                    cmd.ExecuteNonQuery();
                    intReturnValue = (int)returnValueParam.Value;
                }
            }

            return intReturnValue;
        }

