        public DataSet MISAccenture(int clientrowid)
        {
            string Conn = "";
            string ProceName = "";
            DateTime getDt = DateTime.Now;
            string timeSlot = (getDt.Minute < 30 || (getDt.Minute == 30 && getDt.Second == 0))
                ? "BGVMIS_49"
                : "BGVMISTWO_49";
            if (timeSlot == "BGVMIS_49")
            {
                Conn = DAS.BGVMIS_49.ToString();
            }
            else if (timeSlot == "BGVMISTWO_49")
            {
                Conn = DAS.BGVMISTWO_49.ToString();
            }
            DataSet ds = new DataSet();
            if (clientrowid == 860)
            {
                ProceName = "CheckMISAccenture";
            }
            else
            {
                ProceName = "CheckMIS_Client_ALL";
                Conn = DAS.ConnectionString.ToString();
            }
            ds = DAS.ExecuteDataset(Conn, CommandType.StoredProcedure, ProceName,
             DAS.CreateParameter("@clientrowid", SqlDbType.Int, clientrowid, ParameterDirection.Input, 500, false)

      );
            return ds;
        }
