        public int UpdatePQClient(UpdatePQClientViewModel model, int createdBy)
        {
            try
            {
                string ClientSpocName = "";
                string ClientSpocEmail = "";
                //===============================
                DataTable AddressModes = new DataTable();
                AddressModes.Columns.Add("AddressMode", typeof(string));
                if (model.AddressMode != null)
                {
                    string[] Modes = model.AddressMode.Split(',');
                    for (int i = 0; Modes.Length > i; i++)
                    {
                        AddressModes.Rows.Add(Modes[i]);
                    }
                }

                //==============================
                DataTable ClientSpoceDetailsType = new DataTable();
                ClientSpoceDetailsType.Columns.Add("MemberSpocID", typeof(int));
                ClientSpoceDetailsType.Columns.Add("SpocType", typeof(int));
                string[] Spocid = model.SpocName.Split(',');

                for (int i = 0; Spocid.Length > i; i++)
                {
                    ClientSpoceDetailsType.Rows.Add(Spocid[i], 0);

                }
                string[] Spocid1 = model.SecondarySpocName.Split(',');
                for (int i = 0; Spocid1.Length > i; i++)
                {
                    ClientSpoceDetailsType.Rows.Add(Spocid1[i], 1);
                }
                var Spoc = "";
                if (model.SpocName.Length > 0)
                {
                    Spoc = model.SpocName;
                }
                if (model.SecondarySpocName.Length > 0)
                {
                    Spoc += "," + model.SecondarySpocName;
                }

                var SpocDt = GetSpoceNameAndEmail(Spoc);
                if (SpocDt.Rows.Count > 0)
                {
                    for (int i = 0; SpocDt.Rows.Count > i; i++)
                    {
                        if (i == 0)
                        {
                            ClientSpocName = Convert.ToString(SpocDt.Rows[i]["SpocName"]);
                            ClientSpocEmail = Convert.ToString(SpocDt.Rows[i]["EmailID"]);
                        }
                        ClientSpocName = ClientSpocName + "," + SpocDt.Rows[i]["SpocName"];
                        ClientSpocEmail = ClientSpocEmail + "," + SpocDt.Rows[i]["EmailID"];

                    }

                }

                if (model != null && model.ClientRowID > 0)
                {
                    int intReturnValue = 0;
                    SqlParameter objReturnValueParam = DAS.CreateParameter(SP_PARAM_RETURN_VALUE, SqlDbType.Int, null, ParameterDirection.ReturnValue, 0, false);
                    DAS.ExecuteNonQuery(DAS.ConnectionString, CommandType.StoredProcedure, "UpdatePQClientMasters",
            DAS.CreateParameter("@ClientRowID", SqlDbType.BigInt, model.ClientRowID, ParameterDirection.Input, 25, false),
            DAS.CreateParameter("@Address", SqlDbType.NVarChar, model.Address, ParameterDirection.Input, 300, false),
            DAS.CreateParameter("@RegisteredAddress", SqlDbType.NVarChar, model.RegisteredAddress, ParameterDirection.Input, 300, false),
             DAS.CreateParameter("@CorporateOfficeAddress", SqlDbType.NVarChar, model.CorporateOfficeAddress, ParameterDirection.Input, 300, false),
            DAS.CreateParameter("@CodeGeneration", SqlDbType.TinyInt, model.CodeGeneration, ParameterDirection.Input, 25, false),
            DAS.CreateParameter("@BORowID", SqlDbType.SmallInt, model.BORowID, ParameterDirection.Input, 25, false),
            DAS.CreateParameter("@BillingRowID", SqlDbType.TinyInt, model.BillingRowID, ParameterDirection.Input, 25, false),
            DAS.CreateParameter("@ReportSentBy", SqlDbType.TinyInt, model.ReportSentBy, ParameterDirection.Input, 25, false),
            DAS.CreateParameter("@InterimReport", SqlDbType.TinyInt, model.InterimReport, ParameterDirection.Input, 25, false),
            DAS.CreateParameter("@ContractDate", SqlDbType.DateTime, model.ContractDate, ParameterDirection.Input, 100, false),
            DAS.CreateParameter("@ContractComplitionDate", SqlDbType.DateTime, model.ContractComplitionDate, ParameterDirection.Input, 100, false),
            DAS.CreateParameter("@PricingType", SqlDbType.TinyInt, model.PricingType, ParameterDirection.Input, 25, false),
            DAS.CreateParameter("@PaymentTermIndays", SqlDbType.TinyInt, model.PaymentTermIndays, ParameterDirection.Input, 25, false),
            DAS.CreateParameter("@SpecialInstructions", SqlDbType.NVarChar, model.SpecialInstructions, ParameterDirection.Input, 2000, false),
            DAS.CreateParameter("@MapAntecedent", SqlDbType.TinyInt, model.MapAntecedent, ParameterDirection.Input, 25, false),
            DAS.CreateParameter("@MapDisposition", SqlDbType.TinyInt, model.MapDisposition, ParameterDirection.Input, 25, false),
            DAS.CreateParameter("@MapSeverity", SqlDbType.TinyInt, model.MapSeverity, ParameterDirection.Input, 25, false),
            DAS.CreateParameter("@MapHolidays", SqlDbType.TinyInt, model.MapHolidays, ParameterDirection.Input, 25, false),
            DAS.CreateParameter("@MailSendBy", SqlDbType.TinyInt, model.MailSendBy, ParameterDirection.Input, 25, false),
            DAS.CreateParameter("@HRApprovalRequired", SqlDbType.TinyInt, model.HRApprovalRequired, ParameterDirection.Input, 25, false),
