                        DAS.CreateParameter("@SendFundsApprovedMail", SqlDbType.VarChar, model.SendFundsApprovedMail, ParameterDirection.Input, 1000, false),
                        DAS.CreateParameter("@SendYTRMail", SqlDbType.VarChar, model.SendYTRMail, ParameterDirection.Input, 1000, false),
                        DAS.CreateParameter("@ReportVisibilityInterim", SqlDbType.TinyInt, ReportVisibilityInterim, ParameterDirection.Input, 10, false),
