        public void PQVerifiedUploadDocs_Insert(int personalRowID, string DocumentUploadFrom, string DocumentType, string FileName, string FilePath, string Remarks)
        {
            int SubCheckRowID = 0;
            if (DocumentType == "Letter Of Authorization")
            {
                SubCheckRowID = 526;
            }
            if (DocumentType == "BGV Page")
            {
                SubCheckRowID = 527;
            }
            if (SubCheckRowID > 0)
            {
                DAS.ExecuteNonQuery(DAS.ConnectionString, CommandType.StoredProcedure, "usp_PQVerifiedUploadDocs_Insert",
                DAS.CreateParameter("@PersonalRowID", SqlDbType.Int, personalRowID, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@SubCheckRowID", SqlDbType.Int, SubCheckRowID, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@DocumentUploadFrom", SqlDbType.NVarChar, DocumentUploadFrom, ParameterDirection.Input, 20, false),
                DAS.CreateParameter("@DocumentType", SqlDbType.NVarChar, DocumentType, ParameterDirection.Input, 50, false),
                DAS.CreateParameter("@FileName", SqlDbType.NVarChar, FileName, ParameterDirection.Input, 300, false),
                DAS.CreateParameter("@FilePath", SqlDbType.NVarChar, FilePath, ParameterDirection.Input, 600, false),
                DAS.CreateParameter("@Remarks", SqlDbType.NVarChar, Remarks, ParameterDirection.Input, 500, false)
                  );
            }

        }
        public void UpdatePQVerifiedUploadDocs(IEnumerable<MapUploadedDocRWQCTMModel> model, int PersonalRowID, int SubCheckRowId)
        {
            try
            {
                foreach (var item in model)
                {
                    DAS.ExecuteNonQuery(DAS.ConnectionString, CommandType.StoredProcedure, "usp_UpdatePQVerifiedUploadDocs",
                    DAS.CreateParameter("@VerifiedUploadRowID", SqlDbType.BigInt, item.VerifiedUploadRowID, ParameterDirection.Input, 10, false),
                    DAS.CreateParameter("@PersonalRowID", SqlDbType.Int, PersonalRowID, ParameterDirection.Input, 100, false),
                    DAS.CreateParameter("@ClientRowId", SqlDbType.Int, item.ClientRowId, ParameterDirection.Input, 100, false),
                    DAS.CreateParameter("@SubCheckRowId", SqlDbType.Int, SubCheckRowId, ParameterDirection.Input, 100, false),
                    DAS.CreateParameter("@RptArtiFacts", SqlDbType.TinyInt, item.RptArtiFacts, ParameterDirection.Input, 100, false),
                    DAS.CreateParameter("@RptDisplayOrder", SqlDbType.TinyInt, item.RptArtiFactOrder, ParameterDirection.Input, 100, false),
                    DAS.CreateParameter("@NewDocType", SqlDbType.NVarChar, item.NewDocType, ParameterDirection.Input, 100, false),
                    DAS.CreateParameter("@DocumentType", SqlDbType.NVarChar, item.DocType, ParameterDirection.Input, 100, false),
                    DAS.CreateParameter("@DocumentUploadFrom", SqlDbType.NVarChar, item.DocFrom, ParameterDirection.Input, 100, false),
                    DAS.CreateParameter("@FileName", SqlDbType.NVarChar, item.DocName, ParameterDirection.Input, 300, false),
                    DAS.CreateParameter("@FilePath", SqlDbType.NVarChar, item.DocPath, ParameterDirection.Input, 600, false)
                      );
                }
            }
            catch (Exception ex)
            {
                string str = ex.Message;
            }
        }
