        public DataTable TCSION_CRC_SPRCIAL(string DateFrom, string DateTo)
        {
            string Conn = "";
            DateTime getDt = DateTime.Now;
            string timeSlot = (getDt.Minute < 30 || (getDt.Minute == 30 && getDt.Second == 0))
                ? "BGVMIS_49"
                : "BGVMISTWO_49";
            if (timeSlot == "BGVMIS_49")
            {
                Conn = DAS.BGVMIS_49.ToString();
            }
            else if (timeSlot == "BGVMISTWO_49")
            {
                Conn = DAS.BGVMISTWO_49.ToString();
            }
            else
            {
                Conn = DAS.ConnectionString.ToString();
            }
            DataTable dt = new DataTable();
            dt = DAS.ExecuteDataTable(Conn, CommandType.StoredProcedure, "MIS_Client_common_TCSION_CRC_special",
                 DAS.CreateParameter("@dateFROM", SqlDbType.VarChar, DateFrom, ParameterDirection.Input, 50, false),
                 DAS.CreateParameter("@dateTo", SqlDbType.VarChar, DateTo, ParameterDirection.Input, 50, false)

            );
            return dt;
        }
