                EmploymentHistory.Columns.Add("date_of_joining", typeof(string));
                EmploymentHistory.Columns.Add("date_of_exit", typeof(string));
                EmploymentHistory.Columns.Add("last_pf_submitted", typeof(string));
                var employment_history = model.data.employment_history;
                foreach (var item in employment_history)
                {
                    EmploymentHistory.Rows.Add(item.name, item.guardian_name, item.establishment_name, item.member_id, item.date_of_joining, item.date_of_exit, item.last_pf_submitted);

                }
