                    DAS.CreateParameter("@client_id", SqlDbType.VarChar, model.data.client_id, ParameterDirection.Input, 200, false),
                      DAS.CreateParameter("@VerifyedBy", SqlDbType.Int, CreatedBy, ParameterDirection.Input, 10, false),
                       DAS.CreateParameter("@VendorName", SqlDbType.VarChar, VendorName, ParameterDirection.Input, 200, false),
                     DAS.CreateParameter("@SprintVerifyEmploymentHistory", SqlDbType.Structured, EmploymentHistory, ParameterDirection.Input, 30, false),
