        public void InsertToPurg(int ClientRowID, DateTime DateFrom, DateTime DateTo, string filename, string FilePath, HttpPostedFileBase file, int TeamMemberRowId, string OriginalFileName, string Remarks)
        {
            if (file != null)
            {
                DAS.ExecuteNonQuery(DAS.ConnectionString, CommandType.StoredProcedure, "SP_InsertPurgData",
                DAS.CreateParameter("@Clientrow", SqlDbType.Int, ClientRowID, ParameterDirection.Input, 10, false),
                DAS.CreateParameter("@DateFrom", SqlDbType.Date, DateFrom, ParameterDirection.Input, 10, false),
                DAS.CreateParameter("@DateTo", SqlDbType.Date, DateTo, ParameterDirection.Input, 10, false),
                DAS.CreateParameter("@FileName", SqlDbType.Text, filename, ParameterDirection.Input, 500, false),
                DAS.CreateParameter("@FilePath", SqlDbType.Text, FilePath, ParameterDirection.Input, 500, false),
                DAS.CreateParameter("@TeamMemberRowId", SqlDbType.Int, TeamMemberRowId, ParameterDirection.Input, 10, false),
                 DAS.CreateParameter("@OriginalFileName", SqlDbType.Text, OriginalFileName, ParameterDirection.Input, 500, false),
                DAS.CreateParameter("@remarks", SqlDbType.Text, Remarks, ParameterDirection.Input, 1000, false)
                );
            }
            else
