        public string InsertIntoFaceMatch(FaceMatchRoot model, int PersonalRowid, string Image1Name, string Image2Name, string Image1Remark, string Image2Remark, int CreatedBy)
        {
            try
            {
                int status = 0;
                if (model.status == true)
                {
                    status = 1;
                }
                string intReturnValue = "";
                string SP_PARAM_RETURN_VALUE = null;
                if (model.statuscode == 200)
                {
                    SqlParameter objReturnValueParam = DAS.CreateParameter(SP_PARAM_RETURN_VALUE, SqlDbType.Int, null, ParameterDirection.ReturnValue, 0, false);
                    DAS.ExecuteNonQuery(DAS.ConnectionString, CommandType.StoredProcedure, "SpInsertIntoPaysPrintVerifyFaceMatch",
                        DAS.CreateParameter("@PersonalRowid", SqlDbType.Int, PersonalRowid, ParameterDirection.Input, 50, false),
                        DAS.CreateParameter("@statuscode", SqlDbType.Int, model.statuscode, ParameterDirection.Input, 10, false),
                        DAS.CreateParameter("@status", SqlDbType.Int, status, ParameterDirection.Input, 10, false),
                        DAS.CreateParameter("@message", SqlDbType.VarChar, model.message, ParameterDirection.Input, 200, false),
                        DAS.CreateParameter("@reference_id", SqlDbType.Int, PersonalRowid, ParameterDirection.Input, 10, false),
                        DAS.CreateParameter("@statusData", SqlDbType.VarChar, model.data.status, ParameterDirection.Input, 00, false),
                        DAS.CreateParameter("@match", SqlDbType.VarChar, model.data.match, ParameterDirection.Input, 100, false),
                        DAS.CreateParameter("@Image1Name", SqlDbType.VarChar, Image1Name, ParameterDirection.Input, 200, false),
                        DAS.CreateParameter("@Image2Name", SqlDbType.VarChar, Image2Name, ParameterDirection.Input, 200, false),
                        DAS.CreateParameter("@Image1Remark", SqlDbType.VarChar, Image1Remark, ParameterDirection.Input, 200, false),
                        DAS.CreateParameter("@Image2Remark", SqlDbType.VarChar, Image2Remark, ParameterDirection.Input, 200, false),
                        DAS.CreateParameter("@CreatedBy", SqlDbType.Int, CreatedBy, ParameterDirection.Input, 10, false),
                        DAS.CreateParameter("@JsonString1", SqlDbType.NVarChar, CreatedBy, ParameterDirection.Input, int.MaxValue, false),
                        DAS.CreateParameter("@JsonString2", SqlDbType.NVarChar, CreatedBy, ParameterDirection.Input, int.MaxValue, false),
                        objReturnValueParam
                        );
                    intReturnValue = objReturnValueParam.Value.ToString();
                    return intReturnValue;
                }
