        public int insertWorldCheckscreeningRequest(int PersonalRowId, int SubCheckRowId, string ResultJson, string CaseId)
        {
            int intReturnValue = 0;
            using (SqlConnection connection = new SqlConnection(DAS.ConnectionString))
            {
                using (SqlCommand command = new SqlCommand("Sp_insertWorldCheckscreeningRequest", connection))
                {
                    command.CommandType = CommandType.StoredProcedure;
                    // Adding parameters
                    command.Parameters.AddWithValue("@PersonalRowId", PersonalRowId);
                    command.Parameters.AddWithValue("@SubCheckRowId", SubCheckRowId);
                    command.Parameters.AddWithValue("@JsonResult", ResultJson);
                    command.Parameters.AddWithValue("@CaseId", CaseId);
                    try
                    {
                        connection.Open();
                        intReturnValue = command.ExecuteNonQuery();
                        connection.Close();
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine("Error: " + ex.Message);
                    }
                }
            }

            return intReturnValue;
        }
        public int InsertWorldCheckReference_providers(providersRootobject Obj)
        {
            string code = Obj.code;
            string Main_identifier = Obj.identifier;
            int Master = Convert.ToInt32(Obj.master);
            string Main_name = Obj.name;
            foreach (var itemsources in Obj.sources)
            {
                int intReturnValue = 0;
                SqlParameter objReturnValueParam = DAS.CreateParameter(SP_PARAM_RETURN_VALUE, SqlDbType.Int, null, ParameterDirection.ReturnValue, 0, false);
                DAS.ExecuteNonQuery(DAS.ConnectionString, CommandType.StoredProcedure, "Sp_InsertWorldCheckReference_providers",
                DAS.CreateParameter("@code", SqlDbType.VarChar, code, ParameterDirection.Input, 10, false),
                DAS.CreateParameter("@Main_identifier", SqlDbType.VarChar, Main_identifier, ParameterDirection.Input, 10, false),
                DAS.CreateParameter("@Main_master", SqlDbType.Int, Master, ParameterDirection.Input, 10, false),
                DAS.CreateParameter("@Check_name", SqlDbType.VarChar, Main_name, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@abbreviation", SqlDbType.VarChar, itemsources.abbreviation, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@creationDate", SqlDbType.VarChar, itemsources.creationDate, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@identifier", SqlDbType.VarChar, itemsources.identifier, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@importIdentifier", SqlDbType.VarChar, itemsources.importIdentifier, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@name", SqlDbType.VarChar, itemsources.name, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@provider", SqlDbType.VarChar, itemsources.provider, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@providerSourceStatus", SqlDbType.VarChar, itemsources.providerSourceStatus, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@regionOfAuthority", SqlDbType.VarChar, itemsources.regionOfAuthority, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@subscriptionCategory", SqlDbType.VarChar, itemsources.subscriptionCategory, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@modificationDate", SqlDbType.VarChar, itemsources.modificationDate, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@description", SqlDbType.VarChar, itemsources.description, ParameterDirection.Input, 100, false),
