        public int InsertWorldCheckIdentityDocumentLocationType(IdentityDocumentLocationTypeRoot Obj)
        {
            foreach (var itemsources in Obj.identityDocumentLocationTypes)
            {
                string entityTypes = "";
                foreach (var item in itemsources.entityTypes)
                {
                    if (entityTypes == "")
                    {
                        entityTypes = item;
                    }
                    else
                    {
                        entityTypes = entityTypes + "," + item;
                    }
                }
                int intReturnValue = 0;
                SqlParameter objReturnValueParam = DAS.CreateParameter(SP_PARAM_RETURN_VALUE, SqlDbType.Int, null, ParameterDirection.ReturnValue, 0, false);
                DAS.ExecuteNonQuery(DAS.ConnectionString, CommandType.StoredProcedure, "Sp_InsertWorldCheckIdentityDocumentLocationType",
                DAS.CreateParameter("@countrycode", SqlDbType.VarChar, itemsources.country.code, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@countryname", SqlDbType.VarChar, itemsources.country.name, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@name", SqlDbType.VarChar, itemsources.name, ParameterDirection.Input, 200, false),
                DAS.CreateParameter("@type", SqlDbType.VarChar, itemsources.type, ParameterDirection.Input, 100, false),
                DAS.CreateParameter("@entityTypes", SqlDbType.VarChar, entityTypes, ParameterDirection.Input, 100, false),
                objReturnValueParam);
                intReturnValue = (int)objReturnValueParam.Value;
            }

            return 0;
        }
