        public int InsertUpdatePerfiosDL(PerfiosDLRoot Obj, int PersonalRowId, string DLNo, string imgPath, int VerifyedBy, int SubCheckRowId)
        {
            int intReturnValue = 0;

            DataTable AddressObj = new DataTable();

            DataTable covDetails = new DataTable();

            covDetails.Columns.Add("COV", typeof(string));
            covDetails.Columns.Add("Issuedate", typeof(string));

            AddressObj.Columns.Add("addressLine1", typeof(string));
            AddressObj.Columns.Add("state", typeof(string));
            AddressObj.Columns.Add("district", typeof(string));
            AddressObj.Columns.Add("pin", typeof(string));
            AddressObj.Columns.Add("completeAddress", typeof(string));
            AddressObj.Columns.Add("country", typeof(string));
            AddressObj.Columns.Add("type", typeof(string));

            var Address_Obj = Obj.result.address;
            if (Address_Obj.Length > 0)
            {
                foreach (var item in Address_Obj)
                {
                    AddressObj.Rows.Add(item.addressLine1, item.state, item.district, item.pin, item.completeAddress, item.country, item.type);
                }

            }
            if (Obj.result.covDetails.Count > 0)
            {
                foreach (var item in Obj.result.covDetails)
                {
                    covDetails.Rows.Add(item.cov, item.issueDate);
                }
            }

            SqlParameter objReturnValueParam = DAS.CreateParameter(SP_PARAM_RETURN_VALUE, SqlDbType.Int, null, ParameterDirection.ReturnValue, 0, false);
            DAS.ExecuteNonQuery(DAS.ConnectionString, CommandType.StoredProcedure, "InsertUpdatePerfiosDL",
            DAS.CreateParameter("@PersonalRowId", SqlDbType.Int, PersonalRowId, ParameterDirection.Input, 10, false),
            DAS.CreateParameter("@SubCheckRowId", SqlDbType.Int, SubCheckRowId, ParameterDirection.Input, 10, false),
            DAS.CreateParameter("@issueDate", SqlDbType.VarChar, Obj.result.issueDate, ParameterDirection.Input, 20, false),
            DAS.CreateParameter("@fatherhusband", SqlDbType.VarChar, Obj.result.fatherhusband, ParameterDirection.Input, 100, false),
            DAS.CreateParameter("@name", SqlDbType.VarChar, Obj.result.name, ParameterDirection.Input, 100, false),
            DAS.CreateParameter("@img", SqlDbType.VarChar, Obj.result.img, ParameterDirection.Input, 100, false),
            DAS.CreateParameter("@imgPath", SqlDbType.VarChar, imgPath, ParameterDirection.Input, 100, false),
            DAS.CreateParameter("@bloodGroup", SqlDbType.VarChar, Obj.result.bloodGroup, ParameterDirection.Input, 10, false),
            DAS.CreateParameter("@dob", SqlDbType.VarChar, Obj.result.dob, ParameterDirection.Input, 20, false),
            DAS.CreateParameter("@dlNumber", SqlDbType.VarChar, Obj.result.dlNumber, ParameterDirection.Input, 30, false),
            DAS.CreateParameter("@nonTransport", SqlDbType.VarChar, Obj.result.validity.nonTransport, ParameterDirection.Input, 50, false),
            DAS.CreateParameter("@transport", SqlDbType.VarChar, Obj.result.validity.transport, ParameterDirection.Input, 50, false),
            DAS.CreateParameter("@address", SqlDbType.VarChar, "", ParameterDirection.Input, 200, false),
            DAS.CreateParameter("@status", SqlDbType.VarChar, Obj.result.status, ParameterDirection.Input, 10, false),
            DAS.CreateParameter("@initialIssuingOffice", SqlDbType.VarChar, Obj.result.endorsementAndHazardousDetails.initialIssuingOffice, ParameterDirection.Input, 200, false),
            DAS.CreateParameter("@lastEndorsementDate", SqlDbType.VarChar, Obj.result.endorsementAndHazardousDetails.lastEndorsementDate, ParameterDirection.Input, 200, false),
            DAS.CreateParameter("@lastEndorsedOffice", SqlDbType.VarChar, Obj.result.endorsementAndHazardousDetails.lastEndorsedOffice, ParameterDirection.Input, 200, false),
            DAS.CreateParameter("@endorsementReason", SqlDbType.VarChar, Obj.result.endorsementAndHazardousDetails.endorsementReason, ParameterDirection.Input, 200, false),
            DAS.CreateParameter("@hazardousValidTill", SqlDbType.VarChar, Obj.result.endorsementAndHazardousDetails.hazardousValidTill, ParameterDirection.Input, 200, false),
            DAS.CreateParameter("@hillValidTill", SqlDbType.VarChar, Obj.result.endorsementAndHazardousDetails.hillValidTill, ParameterDirection.Input, 200, false),
            DAS.CreateParameter("@VerifiedBy", SqlDbType.Int, VerifyedBy, ParameterDirection.Input, 10, false),
            DAS.CreateParameter("@PerfiosdlAddress", SqlDbType.Structured, AddressObj, ParameterDirection.Input, 500, false),
            DAS.CreateParameter("@covDetails", SqlDbType.Structured, covDetails, ParameterDirection.Input, 500, false),
