        public DataSet CheckWiseMISNew_CS_MultipleClient(string clientrowid, int TeamMemberRowId, string dtf, string dtt)
        {
            string Conn = "";
            DateTime getDt = DateTime.Now;
            string timeSlot = (getDt.Minute < 30 || (getDt.Minute == 30 && getDt.Second == 0))
                ? "BGVMIS_49"
                : "BGVMISTWO_49";
            if (timeSlot == "BGVMIS_49")
            {
                Conn = DAS.BGVMIS_49.ToString();
            }
            else if (timeSlot == "BGVMISTWO_49")
            {
                Conn = DAS.BGVMISTWO_49.ToString();
            }
            else
            {
                Conn = DAS.ConnectionString.ToString();
            }
            DataSet ds = new DataSet();
            ds = DAS.ExecuteDataset(Conn, CommandType.StoredProcedure, "MIS_CheckwiseDetails_OpenCases",
            DAS.CreateParameter("@clientrowid", SqlDbType.VarChar, clientrowid, ParameterDirection.Input, 500, false),
              DAS.CreateParameter("@userid", SqlDbType.Int, TeamMemberRowId, ParameterDirection.Input, 50, false),
               DAS.CreateParameter("@dateFROM", SqlDbType.VarChar, dtf, ParameterDirection.Input, 20, false),
             DAS.CreateParameter("@dateTo", SqlDbType.VarChar, dtt, ParameterDirection.Input, 20, false)
            );
            return ds;
        }

