        public string GetCustomMobileByEmail(string to, string cc)
        {
            try
            {
                var recipients = new HashSet<string>();
                foreach (var part in ((to ?? "") + "," + (cc ?? "")).Split(new[] { ',', ';' }, StringSplitOptions.RemoveEmptyEntries))
                {
                    string e = part.Trim().ToLower();
                    if (e.Length > 0) recipients.Add(e);
                }
                if (recipients.Count == 0) return "";

                DataTable dt = DAS.ExecuteDataTable(DAS.ConnectionString, CommandType.StoredProcedure, "GetCustomMobileClients");

                foreach (DataRow r in dt.Rows)
                {
                    string mob = r["CustomMailMobileNo"].ToString().Trim();
                    if (mob.Length == 0) continue;

                    var clientEmails = new HashSet<string>();
                    foreach (var e in (r["SpocEmails"].ToString() + "," + r["LoginEmails"].ToString()).Split(new[] { ',', ';' }, StringSplitOptions.RemoveEmptyEntries))
                    {
                        string ce = e.Trim().ToLower();
                        if (ce.Length > 0 && !ce.EndsWith("@securitas-india.com"))
                            clientEmails.Add(ce);
                    }

                    foreach (var rec in recipients)
                        if (clientEmails.Contains(rec))
                            return mob;
                }
            }
            catch (Exception) { }
            return "";
        }

